import urllib.request,urllib.error,json
items=['/saas/console/login','/saas/console/assets/css/app.css','/saas/console/_core/Bootstrap.php','/saas/console/database/Seed.php']
result=[]
for path in items:
 try:
  req=urllib.request.Request('https://app.ontrackegy.com'+path,headers={'User-Agent':'OnTrack-Console-Health/1.0'})
  with urllib.request.urlopen(req,timeout=5) as response:
   content=response.read(8192)
   result.append({'path':path,'code':response.status,'bytes':len(content),'login_form':b'password' in content})
 except urllib.error.HTTPError as err:result.append({'path':path,'code':err.code})
 except Exception as err:result.append({'path':path,'error':type(err).__name__})
print(json.dumps(result))
